// Rule syntax for the editor: a tokenizer (highlighting, condition count, autocomplete context)
// and the operators that fit each property type. The engine (Test-DgRule via /rules/validate)
// stays the only judge of whether a rule is valid; this file never rejects anything.
import propertyFile from './properties.json';

export type PropertyType = 'String' | 'Boolean' | 'Date' | 'StringCollection' | 'PlanCollection' | 'GroupCollection';

export interface RuleProperty {
  name: string;
  type: PropertyType;
}

/** Properties the engine understands, generated by tools/Export-RuleProperties.ps1. */
export const properties: RuleProperty[] = (propertyFile.properties as RuleProperty[]).slice();

const byLowerName = new Map(properties.map((p) => [p.name.toLowerCase(), p]));

/** Directory extension properties: extension_<appId without dashes>_<name>. */
export const extensionPattern = /^extension_[0-9a-f]{32}_\w+$/i;

export function findProperty(name: string): RuleProperty | undefined {
  const found = byLowerName.get(name.toLowerCase());
  if (found) return found;
  if (extensionPattern.test(name)) return { name, type: 'String' };
  return undefined;
}

/** Operators per type, in Entra's spelling (as the Microsoft rule reference lists them). */
export const operatorsByType: Record<PropertyType, string[]> = {
  String: ['eq', 'ne', 'startsWith', 'notStartsWith', 'contains', 'notContains', 'match', 'notMatch', 'in', 'notIn'],
  Boolean: ['eq', 'ne'],
  Date: ['eq', 'ne', 'le', 'ge'],
  StringCollection: ['contains', 'notContains', 'any', 'all'],
  PlanCollection: ['any', 'all'],
  GroupCollection: ['any'],
};

export const allOperators = [
  'eq',
  'ne',
  'startsWith',
  'notStartsWith',
  'endsWith',
  'notEndsWith',
  'contains',
  'notContains',
  'match',
  'notMatch',
  'in',
  'notIn',
  'le',
  'ge',
  'and',
  'or',
  'not',
  'any',
  'all',
  'plus',
  'minus',
];
const operatorSet = new Set(allOperators.map((o) => o.toLowerCase()));
const logical = new Set(['and', 'or', 'not']);

export type TokenKind = 'property' | 'operator' | 'logical' | 'string' | 'value' | 'punct' | 'unknown';

export interface Token {
  kind: TokenKind;
  text: string;
  from: number;
  to: number;
}

// En dash, em dash and minus sign count as a hyphen, as in the engine.
const dashes = '-–—−';
const punctuation = '()[],';

function operatorName(word: string): string | null {
  const name = dashes.includes(word.charAt(0)) ? word.slice(1) : word;
  return operatorSet.has(name.toLowerCase()) ? name : null;
}

function isPropertyWord(word: string): boolean {
  return /^(user|device|group|assignedPlan)\.\w*$/i.test(word) || word === '_';
}

/** Splits rule text into tokens. Never throws; unclosed strings run to the end. */
export function tokenize(rule: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < rule.length) {
    const c = rule.charAt(i);
    if (/\s/.test(c)) {
      i += 1;
      continue;
    }
    if (punctuation.includes(c)) {
      tokens.push({ kind: 'punct', text: c, from: i, to: i + 1 });
      i += 1;
      continue;
    }
    if (c === '"' || c === "'" || (c === '`' && rule.charAt(i + 1) === '"')) {
      const start = i;
      const quote = c === '`' ? '"' : c;
      i += c === '`' ? 2 : 1;
      while (i < rule.length) {
        const ch = rule.charAt(i);
        if (quote === '"' && ch === '`' && rule.charAt(i + 1) === '"') {
          i += 2;
          continue;
        }
        if (ch === quote) {
          if (quote === "'" && rule.charAt(i + 1) === "'") {
            i += 2;
            continue;
          }
          i += 1;
          break;
        }
        i += 1;
      }
      tokens.push({ kind: 'string', text: rule.slice(start, i), from: start, to: i });
      continue;
    }
    const start = i;
    while (i < rule.length && !/\s/.test(rule.charAt(i)) && !punctuation.includes(rule.charAt(i)) && !'"\''.includes(rule.charAt(i))) {
      i += 1;
    }
    const word = rule.slice(start, i);
    const op = operatorName(word);
    let kind: TokenKind;
    if (op && (dashes.includes(word.charAt(0)) || logical.has(op.toLowerCase()))) {
      kind = logical.has(op.toLowerCase()) ? 'logical' : 'operator';
    } else if (isPropertyWord(word)) {
      kind = 'property';
    } else if (/^(true|false|null|system\.now|\d+)$/i.test(word) || /^[\w.@:-]+$/.test(word)) {
      kind = 'value';
    } else {
      kind = 'unknown';
    }
    tokens.push({ kind, text: word, from: start, to: i });
  }
  return tokens;
}

/**
 * Number of conditions, as shown under the editor. A collection condition with -any or -all
 * (e.g. memberOf) counts once, together with the conditions inside its parentheses.
 */
export function countConditions(rule: string): number {
  const tokens = tokenize(rule);
  let count = 0;
  for (let k = 0; k < tokens.length - 1; k += 1) {
    const token = tokens[k];
    const next = tokens[k + 1];
    if (token?.kind !== 'property' || next?.kind !== 'operator') continue;
    count += 1;
    if (/^[-\u2013\u2014\u2212]?(any|all)$/i.test(next.text)) {
      // Skip the inner expression: from the next "(" to its matching ")".
      let depth = 0;
      let j = k + 2;
      for (; j < tokens.length; j += 1) {
        const text = tokens[j]?.text;
        if (text === '(') depth += 1;
        if (text === ')') {
          depth -= 1;
          if (depth <= 0) break;
        }
      }
      k = j;
    }
  }
  return count;
}

export type CompletionKind = 'property' | 'operator' | 'logical' | 'start' | 'none';

export interface CompletionContext {
  kind: CompletionKind;
  /** Offset where the replaced text starts. */
  from: number;
  /** Property type when kind is operator. */
  type?: PropertyType;
}

/**
 * Decides what to suggest at `pos`: property names after "user.", operators after a property,
 * -and/-or after a complete condition, "user." at the start of a condition.
 */
export function completionContext(rule: string, pos: number): CompletionContext {
  const before = rule.slice(0, pos);
  const propertyMatch = /(?:^|[\s(])user\.(\w*)$/i.exec(before);
  if (propertyMatch) return { kind: 'property', from: pos - (propertyMatch[1]?.length ?? 0) };

  const wordMatch = /[-–—−]?\w*$/.exec(before);
  const word = wordMatch ? wordMatch[0] : '';
  const from = pos - word.length;
  const previous = tokenize(rule.slice(0, from)).filter((t) => t.to <= from);
  const last = previous[previous.length - 1];

  if (!last || (last.kind === 'punct' && last.text === '(') || last.kind === 'logical') {
    return { kind: 'start', from };
  }
  if (last.kind === 'property') {
    const property = findProperty(last.text.replace(/^user\./i, ''));
    return { kind: 'operator', from, type: property?.type ?? 'String' };
  }
  if (last.kind === 'string' || last.kind === 'value' || (last.kind === 'punct' && (last.text === ')' || last.text === ']'))) {
    if (word === '' && !/\s$/.test(before)) return { kind: 'none', from };
    return { kind: 'logical', from };
  }
  return { kind: 'none', from };
}
